/*
 * mo-homes-ui.js — Mandarin Oriental Exceptional Homes on the Homes page.
 *
 * Renders the country filter, property cards, an accessible detail dialog
 * (gallery, specs, DETAILS + ACTIVITIES NEARBY with "More Info"), and the
 * "Request Availability" inquiry form. Data comes from window.WAH_MO_HOMES
 * (generated by scripts/import-mo-homes.mjs) — the source site is never
 * contacted at runtime.
 *
 * These homes are NOT bookable online. The form sends a request to
 * /api/request-availability (server-validated, delivered to the reservations
 * team); dates are the guest's preferences, not confirmed availability.
 *
 * Endpoint override: <meta name="wah-inquiry-endpoint" content="https://…/api/request-availability">
 * (needed when the page is served from a static host without the API, e.g. the GHL embed).
 */
(function () {
  "use strict";
  var root = document.getElementById("mo-homes");
  if (!root) return;
  // The dataset (~350 KB) is fetched only when the section approaches the
  // viewport, unless it is already on the page (e.g. the inlined GHL build).
  var started = false;
  function boot() {
    if (started) return; started = true;
    if (window.WAH_MO_HOMES) return init();
    var src = root.getAttribute("data-src");
    if (!src) return;
    var l0 = document.getElementById("mo-list");
    if (l0) l0.innerHTML = '<p class="mo-loading" role="status">Loading the collection…</p>';
    var s = document.createElement("script");
    s.src = src; s.async = true;
    s.onload = init;
    s.onerror = function () {
      var list = document.getElementById("mo-list");
      if (list) list.innerHTML = '<p class="mo-noscript">The Exceptional Homes collection could not be loaded. Please refresh the page, or email <a href="mailto:Reservations@WhataHotel.com">Reservations@WhataHotel.com</a>.</p>';
    };
    document.head.appendChild(s);
  }
  window.WAH_MO_BOOT = boot;
  if (window.WAH_MO_HOMES || !("IntersectionObserver" in window)) boot();
  else {
    var io = new IntersectionObserver(function (es) { if (es.some(function (e) { return e.isIntersecting; })) { io.disconnect(); boot(); } }, { rootMargin: "1200px 0px" });
    io.observe(root);
    // Deep links / nav clicks straight to the section.
    if (/^#(exceptional-homes|mo-)/.test(location.hash)) boot();
    document.addEventListener("click", function (e) { if (e.target.closest && e.target.closest('a[href="#exceptional-homes"]')) boot(); });
  }

  function init() {
  var DATA = window.WAH_MO_HOMES, F = window.WAH_MO_FORMAT;
  if (!DATA || !DATA.homes || !F) return;

  var HOMES = DATA.homes.slice().sort(function (a, b) { return a.sortOrder - b.sortOrder; });
  var BY_ID = {}; HOMES.forEach(function (h) { BY_ID[h.id] = h; });
  var COUNTRIES = (DATA.meta && DATA.meta.countries) || [];
  var COUNTS = F.countryCounts(HOMES, COUNTRIES);
  var metaEp = document.querySelector('meta[name="wah-inquiry-endpoint"]');
  var ENDPOINT = (metaEp && metaEp.content) || "/api/request-availability";
  var CONTACT = root.getAttribute("data-contact") || "Reservations@WhataHotel.com";
  var MOBILE = (window.innerWidth || 1024) <= 820;
  var state = { country: "all" };

  var $ = function (sel, el) { return (el || document).querySelector(sel); };
  var $$ = function (sel, el) { return Array.prototype.slice.call((el || document).querySelectorAll(sel)); };
  function esc(s) { return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]; }); }
  function track(event, params) { // analytics: never personal data
    try { (window.dataLayer = window.dataLayer || []).push(Object.assign({ event: event }, params || {})); } catch (e) {}
  }
  var ICON = {
    bed: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 18V8M3 14h18v4M21 14v-2a3 3 0 00-3-3h-7v5"/><circle cx="7" cy="11" r="1.6"/></svg>',
    bath: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 12h16v3a4 4 0 01-4 4H8a4 4 0 01-4-4v-3zM6 12V6a2 2 0 014 0M7 19l-1 2M17 19l1 2"/></svg>',
    guests: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="9" cy="8" r="3"/><path d="M3 20c0-3.3 2.7-6 6-6s6 2.7 6 6"/><circle cx="17" cy="9" r="2.4"/><path d="M15.5 14.3A5 5 0 0121 19"/></svg>',
    pin: '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2C8 2 5 5 5 9c0 5 7 13 7 13s7-8 7-13c0-4-3-7-7-7zm0 9.5A2.5 2.5 0 1112 6a2.5 2.5 0 010 5.5z"/></svg>',
    close: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>',
    prev: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 6l-6 6 6 6"/></svg>',
    next: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg>'
  };

  /* ---------------- shared bits ---------------- */
  function placeLine(h) { // "Chiang Rai, Thailand" stays as is; "Uluwatu, Bali" → "Uluwatu, Bali · Indonesia"
    var loc = h.location || "";
    return loc && loc.toLowerCase().indexOf(String(h.country).toLowerCase()) !== -1 ? loc : [loc, h.country].filter(Boolean).join(" · ");
  }
  function imgTag(asset, width, cls, eager) {
    if (!asset) return "";
    var w = MOBILE ? Math.min(width, 720) : width;
    return '<img class="' + cls + '" src="' + esc(F.imageUrl(asset.url, w)) + '" data-raw="' + esc(asset.url) + '" alt="' + esc(asset.alt) + '"' +
      (eager ? "" : ' loading="lazy"') + ' decoding="async" onload="this.classList.add(\'is-loaded\')" ' +
      'onerror="if(this.dataset.fb){this.style.display=\'none\';this.parentNode.classList.add(\'mo-noimg\')}else{this.dataset.fb=1;this.src=this.dataset.raw}">';
  }
  function specs(h, cls) {
    var b = F.formatCount(h.bedroomsDisplay, "Bedroom", "Bedrooms");
    var ba = F.formatCount(h.bathroomsDisplay, "Bathroom", "Bathrooms");
    var g = F.formatCount(h.maxGuestsDisplay, "Guest", "Guests");
    function one(icon, v, label) {
      return '<li class="' + (v.missing ? "is-missing" : "") + '">' + icon +
        '<span>' + (v.missing ? '<span class="visually-hidden">' + label + ': </span>' + esc(label) + " not published" : esc(v.text)) + '</span></li>';
    }
    return '<ul class="' + cls + '">' + one(ICON.bed, b, "Bedrooms") + one(ICON.bath, ba, "Bathrooms") + one(ICON.guests, g, "Guests") + '</ul>';
  }
  function rateHTML(h, cls) {
    var r = F.formatRate(h);
    if (r.missing) return '<p class="' + cls + ' is-missing"><span class="mo-rate__label">Rates</span> <span class="mo-rate__val">on request</span></p>';
    return '<p class="' + cls + '"><span class="mo-rate__label">From</span> <span class="mo-rate__val">' + esc(r.text) + '</span>' + (r.unit ? ' <span class="mo-rate__unit">' + esc(r.unit) + '</span>' : '') + '<span class="mo-rate__flag" aria-hidden="true">*</span></p>';
  }
  function blocksHTML(blocks) {
    return (blocks || []).map(function (b) {
      if (b.type === "list") return '<ul class="mo-rich__list">' + b.items.map(function (i) { return "<li>" + esc(i) + "</li>"; }).join("") + "</ul>";
      if (b.type === "heading") return '<h4 class="mo-rich__h">' + esc(b.text) + "</h4>";
      if (b.type === "labelled") return '<p class="mo-rich__kv"><strong>' + esc(b.label) + ":</strong> " + esc(b.text) + "</p>";
      if (b.type === "note") return '<p class="mo-rich__note">' + esc(b.text) + "</p>";
      return "<p>" + esc(b.text) + "</p>";
    }).join("");
  }

  /* ---------------- filters + list ---------------- */
  function renderFilters() {
    var bar = $("#mo-filters");
    var opts = [{ key: "all", label: "All Homes" }].concat(COUNTRIES.filter(function (c) { return COUNTS[c]; }).map(function (c) { return { key: c, label: c }; }));
    bar.innerHTML = opts.map(function (o) {
      return '<button type="button" class="mo-chip" data-country="' + esc(o.key) + '" aria-pressed="' + (state.country === o.key) + '">' +
        esc(o.label) + ' <span class="mo-chip__n">' + COUNTS[o.key] + '</span></button>';
    }).join("");
  }
  function cardHTML(h) {
    var img = h.imageAssets && h.imageAssets[0];
    return '<article class="mo-card" data-id="' + esc(h.id) + '" aria-labelledby="moc-' + esc(h.id) + '">' +
      '<button type="button" class="mo-card__media' + (img ? "" : " mo-noimg") + '" data-mo-detail="' + esc(h.id) + '" aria-label="View details for ' + esc(h.name) + '">' +
        imgTag(img, 720, "mo-card__img") +
        '<span class="mo-card__badge">' + esc(h.country) + '</span>' +
      '</button>' +
      '<div class="mo-card__body">' +
        '<p class="mo-card__loc">' + ICON.pin + esc(h.location || h.region || h.country) + '</p>' +
        '<h4 class="mo-card__name" id="moc-' + esc(h.id) + '">' + esc(h.name) + '</h4>' +
        specs(h, "mo-specs") +
        rateHTML(h, "mo-rate") +
        '<div class="mo-card__actions">' +
          '<button type="button" class="btn btn-outline mo-btn" data-mo-detail="' + esc(h.id) + '" aria-label="View details for ' + esc(h.name) + '">View Details</button>' +
          '<button type="button" class="btn btn-primary mo-btn" data-mo-request="' + esc(h.id) + '" aria-label="Request availability for ' + esc(h.name) + '">Request Availability</button>' +
        '</div>' +
      '</div>' +
    '</article>';
  }
  function renderList() {
    var list = $("#mo-list");
    var homes = F.filterHomes(HOMES, state.country);
    var html;
    if (state.country === "all") {
      html = COUNTRIES.filter(function (c) { return COUNTS[c]; }).map(function (c) {
        var group = homes.filter(function (h) { return h.country === c; });
        return '<section class="mo-group" aria-labelledby="mog-' + esc(c.replace(/\W+/g, "-")) + '">' +
          '<h3 class="mo-group__title" id="mog-' + esc(c.replace(/\W+/g, "-")) + '">' + esc(c) + ' <span>' + group.length + (group.length === 1 ? " home" : " homes") + '</span></h3>' +
          '<div class="mo-grid">' + group.map(cardHTML).join("") + '</div></section>';
      }).join("");
    } else {
      html = '<div class="mo-grid">' + homes.map(cardHTML).join("") + '</div>';
    }
    list.innerHTML = html;
    var live = $("#mo-status");
    if (live) live.textContent = "Showing " + homes.length + (homes.length === 1 ? " home" : " homes") + (state.country === "all" ? " in all countries" : " in " + state.country) + ".";
  }
  function setCountry(c) {
    state.country = c;
    $$(".mo-chip", root).forEach(function (b) { b.setAttribute("aria-pressed", String(b.getAttribute("data-country") === c)); });
    renderList();
    track("mo_filter", { country: c });
  }

  /* ---------------- detail dialog ---------------- */
  var detail = $("#mo-detail"), detailBody = $("#mo-detail-body");
  var gallery = { list: [], i: 0 };
  function galleryShow(i) {
    if (!gallery.list.length) return;
    gallery.i = (i + gallery.list.length) % gallery.list.length;
    var a = gallery.list[gallery.i], main = $(".mo-gal__main", detailBody);
    main.innerHTML = imgTag(a, 1400, "mo-gal__img", true);
    $(".mo-gal__count", detailBody).textContent = (gallery.i + 1) + " / " + gallery.list.length;
    $$(".mo-gal__thumb", detailBody).forEach(function (t, k) { t.setAttribute("aria-current", k === gallery.i ? "true" : "false"); });
  }
  function sectionHTML(id, title, blocks) {
    if (!blocks || !blocks.length) {
      return '<section class="mo-sec" aria-labelledby="' + id + '-h"><h3 class="mo-sec__title" id="' + id + '-h">' + esc(title) + '</h3><p class="mo-sec__missing">Not published by the source. Our advisors can share more on request.</p></section>';
    }
    return '<section class="mo-sec" aria-labelledby="' + id + '-h"><h3 class="mo-sec__title" id="' + id + '-h">' + esc(title) + '</h3>' +
      '<div class="mo-rich mo-clamp" id="' + id + '-b">' + blocksHTML(blocks) + '</div>' +
      '<button type="button" class="mo-more" aria-expanded="false" aria-controls="' + id + '-b" hidden>More Info</button></section>';
  }
  // Only clamp when the content is genuinely longer than ~5 rendered lines.
  function measureClamps(scope) {
    $$(".mo-clamp", scope).forEach(function (body) {
      var btn = body.parentNode.querySelector(".mo-more");
      body.classList.add("is-clamped"); body.classList.remove("is-open");
      var over = body.scrollHeight > body.clientHeight + 4;
      if (!over) body.classList.remove("is-clamped");
      if (btn) { btn.hidden = !over; btn.setAttribute("aria-expanded", "false"); btn.textContent = "More Info"; }
    });
  }
  function openDetail(id) {
    var h = BY_ID[id]; if (!h || !detail) return;
    gallery = { list: h.imageAssets || [], i: 0 };
    var thumbs = gallery.list.length > 1 ? '<div class="mo-gal__thumbs" role="group" aria-label="Choose a photograph">' + gallery.list.map(function (a, k) {
      return '<button type="button" class="mo-gal__thumb" data-mo-thumb="' + k + '" aria-label="Show photograph ' + (k + 1) + ' of ' + gallery.list.length + '">' + imgTag(a, 200, "mo-gal__timg") + '</button>';
    }).join("") + '</div>' : "";
    detailBody.innerHTML =
      '<div class="mo-detail__grid">' +
        '<div class="mo-gal' + (gallery.list.length ? "" : " mo-noimg") + '">' +
          '<div class="mo-gal__stage"><div class="mo-gal__main"></div>' +
          (gallery.list.length > 1 ? '<button type="button" class="mo-gal__nav mo-gal__prev" data-mo-gal="-1" aria-label="Previous photograph">' + ICON.prev + '</button><button type="button" class="mo-gal__nav mo-gal__next" data-mo-gal="1" aria-label="Next photograph">' + ICON.next + '</button>' : "") +
          (gallery.list.length ? '<span class="mo-gal__count" aria-live="polite"></span>' : "") + '</div>' + thumbs +
          (gallery.list.length ? '<p class="mo-credit">' + esc(gallery.list[0].credit || "") + '</p>' : "") +
        '</div>' +
        '<div class="mo-detail__info">' +
          '<p class="mo-detail__eyebrow">Mandarin Oriental Exceptional Homes · ' + esc(h.country) + '</p>' +
          '<h2 class="mo-detail__name" id="mo-detail-title">' + esc(h.name) + '</h2>' +
          '<p class="mo-detail__loc">' + ICON.pin + esc(h.location || h.country) + '</p>' +
          specs(h, "mo-specs mo-specs--lg") +
          rateHTML(h, "mo-rate mo-rate--lg") +
          '<p class="mo-fine">*Indicative starting rate published by Mandarin Oriental, subject to confirmation. Not bookable online; your advisor confirms availability and the final rate.</p>' +
          '<div class="mo-detail__cta"><button type="button" class="btn btn-primary btn-lg" data-mo-request="' + esc(h.id) + '">Request Availability</button></div>' +
          sectionHTML("mo-det", "Details", h.details) +
          sectionHTML("mo-act", "Activities Nearby", h.activitiesNearby) +
          '<p class="mo-source">Source: <a href="' + esc(h.sourceUrl) + '" target="_blank" rel="noopener">Mandarin Oriental — ' + esc(h.name) + '</a></p>' +
        '</div>' +
      '</div>';
    if (gallery.list.length) galleryShow(0);
    if (typeof detail.showModal === "function") detail.showModal(); else detail.setAttribute("open", "");
    document.documentElement.classList.add("mo-lock");
    detail.scrollTop = 0;
    measureClamps(detailBody);
    track("mo_view_details", { property_id: h.id });
  }
  function closeDialog(d) {
    if (!d) return;
    if (typeof d.close === "function") d.close();
    else { d.removeAttribute("open"); d.dispatchEvent(new Event("close")); }
  }

  /* ---------------- request dialog ---------------- */
  var req = $("#mo-request"), form = $("#mo-form"), reqState = { submitting: false, openedAt: 0, submissionId: null };
  function uuid() {
    if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
    return "s-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 10);
  }
  function isoDate(d) { var z = new Date(d.getTime() - d.getTimezoneOffset() * 60000); return z.toISOString().slice(0, 10); }
  function openRequest(id) {
    var h = BY_ID[id]; if (!h || !req) return;
    form.reset();
    $$(".mo-field__err", form).forEach(function (e) { e.textContent = ""; });
    $$("[aria-invalid]", form).forEach(function (e) { e.removeAttribute("aria-invalid"); });
    $("#mo-f-property-id").value = h.id;
    $("#mo-f-source").value = h.sourceUrl;
    $("#mo-f-country").value = h.country;
    $("#mo-req-home").textContent = h.name;
    $("#mo-req-loc").textContent = placeLine(h);
    var img = h.imageAssets && h.imageAssets[0];
    $("#mo-req-thumb").innerHTML = img ? imgTag(img, 240, "mo-req__img", true) : "";
    var today = isoDate(new Date());
    $("#mo-f-checkin").min = today; $("#mo-f-checkout").min = today;
    $("#mo-f-adults").value = "2"; $("#mo-f-children").value = "0"; $("#mo-f-infants").value = "0";
    form.setAttribute("data-max-guests", h.maxGuests == null ? "" : h.maxGuests);
    updateTotal();
    showView("form");
    reqState = { submitting: false, openedAt: Date.now(), submissionId: uuid() };
    setBusy(false);
    if (typeof req.showModal === "function") req.showModal(); else req.setAttribute("open", "");
    document.documentElement.classList.add("mo-lock");
    req.scrollTop = 0;
    setTimeout(function () { var f = $("#mo-f-name"); if (f) f.focus(); }, 30);
    track("mo_request_opened", { property_id: h.id });
  }
  function showView(which) {
    $("#mo-req-form-view").hidden = which !== "form";
    $("#mo-req-success").hidden = which !== "success";
  }
  function n(v) { return /^\d+$/.test(String(v).trim()) ? Number(v) : NaN; }
  function updateTotal() {
    var a = n($("#mo-f-adults").value), c = n($("#mo-f-children").value || "0"), i = n($("#mo-f-infants").value || "0");
    var t = [a, c, i].every(function (x) { return !isNaN(x); }) ? a + c + i : null;
    $("#mo-f-total").textContent = t == null ? "—" : String(t);
    var max = form.getAttribute("data-max-guests"), note = $("#mo-cap-note");
    if (max && t != null && a + c > Number(max)) { note.hidden = false; note.textContent = "This home's published capacity is " + max + " guests. You can still send your request; our advisors will advise on options."; }
    else note.hidden = true;
  }
  function fieldError(id, msg) {
    var input = $("#" + id), err = $("#" + id + "-err");
    if (err) err.textContent = msg || "";
    if (input) { if (msg) input.setAttribute("aria-invalid", "true"); else input.removeAttribute("aria-invalid"); }
  }
  var EMAIL_RE = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[A-Za-z]{2,}$/;
  function validDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || ""); if (!m) return null;
    var t = Date.UTC(+m[1], +m[2] - 1, +m[3]), d = new Date(t);
    return d.getUTCFullYear() === +m[1] && d.getUTCMonth() === +m[2] - 1 && d.getUTCDate() === +m[3] ? t : null;
  }
  function validate() {
    var errs = {}, v = function (id) { return ($("#" + id).value || "").trim(); };
    if (!v("mo-f-name")) errs["mo-f-name"] = "Please enter your full name.";
    if (!v("mo-f-email")) errs["mo-f-email"] = "Please enter your email address.";
    else if (!EMAIL_RE.test(v("mo-f-email"))) errs["mo-f-email"] = "Please enter a valid email address.";
    var ph = v("mo-f-phone");
    if (ph && (!/^\+?[\d\s().-]{6,}$/.test(ph) || (ph.match(/\d/g) || []).length < 6)) errs["mo-f-phone"] = "Please enter a valid phone number, including the country code.";
    var ci = validDate(v("mo-f-checkin")), co = validDate(v("mo-f-checkout"));
    var t = new Date(), today = Date.UTC(t.getFullYear(), t.getMonth(), t.getDate());
    if (!v("mo-f-checkin")) errs["mo-f-checkin"] = "Please choose your preferred check-in date.";
    else if (ci == null) errs["mo-f-checkin"] = "Please enter a valid check-in date.";
    else if (ci < today) errs["mo-f-checkin"] = "Check-in can't be in the past.";
    if (!v("mo-f-checkout")) errs["mo-f-checkout"] = "Please choose your preferred check-out date.";
    else if (co == null) errs["mo-f-checkout"] = "Please enter a valid check-out date.";
    else if (ci != null && co <= ci) errs["mo-f-checkout"] = "Check-out must be after check-in.";
    var a = n(v("mo-f-adults")), c = n(v("mo-f-children") || "0"), i = n(v("mo-f-infants") || "0");
    if (isNaN(a) || a < 1) errs["mo-f-adults"] = "Please enter at least 1 adult.";
    if (isNaN(c) || c < 0) errs["mo-f-children"] = "Please enter a valid number of children.";
    if (isNaN(i) || i < 0) errs["mo-f-infants"] = "Please enter a valid number of infants.";
    if (!$("#mo-f-consent").checked) errs["mo-f-consent"] = "Please confirm you agree to be contacted about this inquiry.";
    ["mo-f-name", "mo-f-email", "mo-f-phone", "mo-f-checkin", "mo-f-checkout", "mo-f-adults", "mo-f-children", "mo-f-infants", "mo-f-consent"].forEach(function (id) { fieldError(id, errs[id]); });
    return errs;
  }
  var SERVER_FIELD = { fullName: "mo-f-name", email: "mo-f-email", phone: "mo-f-phone", checkIn: "mo-f-checkin", checkOut: "mo-f-checkout", adults: "mo-f-adults", children: "mo-f-children", infants: "mo-f-infants", consent: "mo-f-consent", message: "mo-f-message" };
  function setBusy(on) {
    var btn = $("#mo-f-submit");
    btn.disabled = on; btn.setAttribute("aria-busy", on ? "true" : "false");
    btn.querySelector(".mo-submit__txt").textContent = on ? "Sending your request…" : "Send Request";
    form.setAttribute("aria-busy", on ? "true" : "false");
  }
  function showFormError(msg) {
    var box = $("#mo-form-error");
    box.innerHTML = msg; box.hidden = !msg;
    if (msg) box.focus();
  }
  function submit(e) {
    e.preventDefault();
    if (reqState.submitting) return;               // no duplicate submissions
    showFormError("");
    var errs = validate(), keys = Object.keys(errs);
    if (keys.length) { var first = $("#" + keys[0]); if (first) first.focus(); return; }
    var val = function (id) { return ($("#" + id).value || "").trim(); };
    var payload = {
      propertyId: val("mo-f-property-id"),
      fullName: val("mo-f-name"), email: val("mo-f-email"), phone: val("mo-f-phone"),
      checkIn: val("mo-f-checkin"), checkOut: val("mo-f-checkout"),
      adults: val("mo-f-adults"), children: val("mo-f-children") || "0", infants: val("mo-f-infants") || "0",
      message: val("mo-f-message"), consent: $("#mo-f-consent").checked,
      website: $("#mo-f-website").value,             // honeypot (should stay empty)
      elapsedMs: Date.now() - reqState.openedAt,
      submissionId: reqState.submissionId
    };
    reqState.submitting = true; setBusy(true);
    var ctrl = window.AbortController ? new AbortController() : null;
    var timer = setTimeout(function () { if (ctrl) ctrl.abort(); }, 25000);
    fetch(ENDPOINT, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload), signal: ctrl ? ctrl.signal : undefined })
      .then(function (r) { return r.json().catch(function () { return {}; }).then(function (j) { return { status: r.status, json: j }; }); })
      .then(function (res) {
        clearTimeout(timer);
        if (res.status === 200 && res.json && res.json.ok) {
          $("#mo-req-ref").textContent = res.json.inquiryId ? "Reference: " + res.json.inquiryId : "";
          showView("success");
          var ok = $("#mo-req-success"); if (ok) ok.focus();
          track("mo_request_submitted", { property_id: payload.propertyId });
          return;
        }
        if (res.status === 422 && res.json && res.json.fields) {
          var firstId = null;
          Object.keys(res.json.fields).forEach(function (k) { var id = SERVER_FIELD[k]; if (id) { fieldError(id, res.json.fields[k]); firstId = firstId || id; } });
          if (res.json.fields.propertyId) showFormError(esc(res.json.fields.propertyId));
          if (firstId) $("#" + firstId).focus();
          return;
        }
        var msg = (res.json && res.json.message) ? esc(res.json.message) : "We couldn't send your request just now.";
        showFormError(msg + ' Please try again, or email us at <a href="mailto:' + esc(CONTACT) + '">' + esc(CONTACT) + '</a>.');
        track("mo_request_failed", { property_id: payload.propertyId, status: res.status });
      })
      .catch(function () {
        clearTimeout(timer);
        showFormError('We couldn\'t reach our server. Please check your connection and try again, or email us at <a href="mailto:' + esc(CONTACT) + '">' + esc(CONTACT) + '</a>.');
        track("mo_request_failed", { property_id: payload.propertyId, status: 0 });
      })
      .then(function () { reqState.submitting = false; setBusy(false); });
  }

  /* ---------------- wiring ---------------- */
  renderFilters();
  renderList();
  root.addEventListener("click", function (e) {
    var chip = e.target.closest(".mo-chip");
    if (chip) { setCountry(chip.getAttribute("data-country")); return; }
  });
  document.addEventListener("click", function (e) {
    var d = e.target.closest("[data-mo-detail]");
    if (d) { openDetail(d.getAttribute("data-mo-detail")); return; }
    var r = e.target.closest("[data-mo-request]");
    if (r) { openRequest(r.getAttribute("data-mo-request")); return; }
    var g = e.target.closest("[data-mo-gal]");
    if (g) { galleryShow(gallery.i + Number(g.getAttribute("data-mo-gal"))); return; }
    var t = e.target.closest("[data-mo-thumb]");
    if (t) { galleryShow(Number(t.getAttribute("data-mo-thumb"))); return; }
    var more = e.target.closest(".mo-more");
    if (more) {
      var body = document.getElementById(more.getAttribute("aria-controls"));
      var open = more.getAttribute("aria-expanded") !== "true";
      body.classList.toggle("is-open", open);
      more.setAttribute("aria-expanded", String(open));
      more.textContent = open ? "Show Less" : "More Info";
      if (!open) { var sec = more.closest(".mo-sec"); if (sec && sec.getBoundingClientRect().top < 0) sec.scrollIntoView({ block: "start" }); }
      return;
    }
    var c = e.target.closest("[data-mo-close]");
    if (c) { closeDialog(c.closest("dialog")); return; }
  });
  [detail, req].forEach(function (d) {
    if (!d) return;
    d.addEventListener("click", function (e) { if (e.target === d) closeDialog(d); });   // backdrop click
    d.addEventListener("close", function () {
      if (d === detail) detailBody.innerHTML = "";
      if (!(detail && detail.open) && !(req && req.open)) document.documentElement.classList.remove("mo-lock");
    });
  });
  if (detail) detail.addEventListener("keydown", function (e) {
    if (!gallery.list.length || !e.target.closest || !e.target.closest(".mo-gal")) return;
    if (e.key === "ArrowLeft") { e.preventDefault(); galleryShow(gallery.i - 1); }
    if (e.key === "ArrowRight") { e.preventDefault(); galleryShow(gallery.i + 1); }
  });
  if (form) {
    form.addEventListener("submit", submit);
    ["mo-f-adults", "mo-f-children", "mo-f-infants"].forEach(function (id) { $("#" + id).addEventListener("input", updateTotal); });
    $("#mo-f-checkin").addEventListener("change", function () {
      var ci = validDate(this.value), co = $("#mo-f-checkout");
      if (ci != null) { var next = new Date(ci + 86400000); co.min = next.toISOString().slice(0, 10); if (co.value && validDate(co.value) <= ci) co.value = ""; }
    });
  }
  var rz; window.addEventListener("resize", function () { clearTimeout(rz); rz = setTimeout(function () { if (detail && detail.open) measureClamps(detailBody); }, 200); });

  // Test hooks (no behaviour): expose read-only helpers for automated checks.
  window.WAH_MO_UI = { open: openDetail, request: openRequest, setCountry: setCountry, endpoint: ENDPOINT };
  try { document.dispatchEvent(new Event("wah:mo-ready")); } catch (e) {}
  }
})();
